import React from 'react';
import type { Provider, Quote } from '@metamask/ramps-controller';
import {
  Box,
  BoxAlignItems,
  BoxFlexDirection,
  BoxJustifyContent,
  ButtonBase,
  Icon,
  IconColor,
  IconName,
  IconSize,
  Tag,
  Text,
  TextColor,
  FontWeight,
  TextVariant,
} from '@metamask/design-system-react';
import { useFormatters } from '../../../../hooks/useFormatters';
import { getRampsListItemClassName } from '../../components/get-ramps-list-item-class-name';
import RampsQuoteDisplay, {
  getRampsQuoteAmounts,
  shouldShowSelectedCheckIcon,
} from '../../payment-method/components/ramps-quote-display';
import type { ProviderTag } from '../utils/build-provider-list-items';

export type RampsProviderListItemProps = {
  provider: Provider;
  isSelected?: boolean;
  isDisabled?: boolean;
  tags?: ProviderTag[];
  subtitle?: string | null;
  showQuote?: boolean;
  quote?: Quote | null;
  quoteLoading?: boolean;
  currency?: string;
  tokenSymbol?: string;
  onClick: () => void;
};

/**
 * Provider row matching mobile ProviderSelection: name (+ optional subtitle)
 * on the left, quote amounts on the right.
 * @param options0
 * @param options0.provider
 * @param options0.isSelected
 * @param options0.isDisabled
 * @param options0.tags
 * @param options0.subtitle
 * @param options0.showQuote
 * @param options0.quote
 * @param options0.quoteLoading
 * @param options0.currency
 * @param options0.tokenSymbol
 * @param options0.onClick
 */
export default function RampsProviderListItem({
  provider,
  isSelected = false,
  isDisabled = false,
  tags = [],
  subtitle = null,
  showQuote = false,
  quote = null,
  quoteLoading = false,
  currency = 'USD',
  tokenSymbol = '',
  onClick,
}: RampsProviderListItemProps) {
  const { formatToken, formatCurrency } = useFormatters();

  const { cryptoAmount, fiatAmount } = getRampsQuoteAmounts({
    quote,
    tokenSymbol,
    currency,
    formatToken,
    formatCurrency,
  });
  const showSelectedCheckIcon = shouldShowSelectedCheckIcon({
    isSelected,
    showQuote,
    cryptoAmount,
    fiatAmount,
    isLoading: quoteLoading,
  });

  return (
    <ButtonBase
      onClick={onClick}
      isDisabled={isDisabled}
      className={getRampsListItemClassName(isSelected)}
      data-testid={`ramps-provider-item-${provider.id}`}
    >
      <Box
        className="w-full"
        flexDirection={BoxFlexDirection.Row}
        alignItems={BoxAlignItems.Center}
        justifyContent={BoxJustifyContent.Between}
        gap={3}
      >
        <Box
          className="min-w-0 flex-1"
          flexDirection={BoxFlexDirection.Column}
          alignItems={BoxAlignItems.Start}
          gap={1}
        >
          <Box
            className="w-full min-w-0"
            flexDirection={BoxFlexDirection.Row}
            alignItems={BoxAlignItems.Center}
            gap={2}
          >
            <Text
              variant={TextVariant.BodyMd}
              fontWeight={FontWeight.Medium}
              className="min-w-0 truncate text-left"
              data-testid={`ramps-provider-item-name-${provider.id}`}
            >
              {provider.name}
            </Text>
            {tags.map((tag, index) => (
              <Tag
                key={tag.label}
                severity={tag.severity}
                className="shrink-0 self-center"
                data-testid={`ramps-provider-item-tag-${provider.id}-${index}`}
              >
                {tag.label}
              </Tag>
            ))}
          </Box>
          {subtitle ? (
            <Text
              variant={TextVariant.BodySm}
              color={TextColor.TextAlternative}
              className="truncate text-left"
              data-testid={`ramps-provider-item-subtitle-${provider.id}`}
            >
              {subtitle}
            </Text>
          ) : null}
        </Box>
        {showQuote || isSelected ? (
          <Box
            flexDirection={BoxFlexDirection.Row}
            alignItems={BoxAlignItems.Center}
            gap={2}
            className="shrink-0"
          >
            {showQuote ? (
              <RampsQuoteDisplay
                cryptoAmount={cryptoAmount}
                fiatAmount={fiatAmount}
                isLoading={quoteLoading}
              />
            ) : null}
            {showSelectedCheckIcon ? (
              <Icon
                name={IconName.Check}
                size={IconSize.Md}
                color={IconColor.PrimaryDefault}
                data-testid="ramps-provider-item-selected"
              />
            ) : null}
          </Box>
        ) : null}
      </Box>
    </ButtonBase>
  );
}
